#!/usr/bin/env python3
"""Integrate exact boundary torsion and the unrestricted norm-fibre comparison."""
from pathlib import Path
import datetime,json,subprocess
w=Path(__file__).resolve().parents[1]
stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%H:%M UTC')
records={
 'A.164':{
  'file':'harmonic_jacobian_boundary_torsion.tex',
  'answers':'A5; A10; A15; L7; L10; L14',
  'depends_on':'A.150 literal plane quartic and differentials; A.163 rational divisor isogenies; exact boundary divisors; good reductions at17 and31; actual local halving formulas and Q2 squareclass map',
  'uses_local_theorem':'no',
  'manuscript_passages':'cote149; scans54–55 and56–58; separation of actual proper boundary images in a specified finite quotient',
  'notes':'The rational Jacobian torsion is exactly C4² generated by P0-Pinfinity and P1-Pinfinity. Literal divisors and the canonical plane-quartic embedding prove order4 and independence; exact good-reduction counts give a matching order16 upper bound on all rational torsion. The actual rational isogeny and elementary halving formulas show local J(Q2) two-primary torsion has exponent at most4. Every difference of two boundary points has order4 and cannot be twice a local or rational point. Thus the four boundary images remain distinct in the first two-Kummer quotient on the selected cover sheet. No downstairs deck-conjugacy assertion is added.',
  'detail':'A.164 determines J_D(Q)_tors=C4² and proves that the four boundary images are already separated by the first two-Kummer quotient, including at the physical place two, on a selected cover sheet.'
 },
 'A.166':{
  'file':'two_inert_infinite_support_identity.tex',
  'answers':'A5; A9; A15; L10; L14; L20',
  'depends_on':'A.86 exact completed divisor sequence; A.89 affine Frobenius and weighted ideal norms; A.155 balanced class criterion; A.162 fixed changed seed and exact support quotient; finite S-ideal class group and compact completed S-unit fibres',
  'uses_local_theorem':'no',
  'manuscript_passages':'cote149; scans56–58 and126–127; actual inverse norm maps and the finite-support obstruction for their full fibre',
  'notes':'For the fixed tower a=3*649^24, the natural inclusions identify the unrestricted inverse field-norm fibre over-2 with the fixed-S-unit fibre, separately for actual elements and pro3 completed elements. The proof projects the actual norm-compatible divisors at each physical prime, retains uniform residue-degree growth off the unique possible affine-Frobenius fixed branch, and rules out moving prime support. At2 only the distinguished branch has coefficient1; at3 the coefficient is0;11 and59 carry stable balanced vectors(-2c,c). Completion injectivity is proved using the finite-index principal-divisor lattice. Nonemptiness of the completed unrestricted fibre is therefore exactly all e_n=0 in A155. No such vanishing or actual/completed nonemptiness is asserted. Fixing the A162 first two seeds gives the same comparison and exact finite completed-S fibre criterion.',
  'detail':'A.166 identifies the unrestricted coherent field-norm fibre over-2 with its fixed-S-unit fibre, separately for actual and completed elements. Its completed existence question is exactly the all-height balanced class test of A.155; finite field-norm solvability in A.162 has not yet established that test.'
 }
}
p=w/'SECTIONS_OVER_Q_paper.tex';s=p.read_text()
anchor=r'\input{sections/harmonic_proper_abelian_classification.tex}'
assert anchor in s
new='\n'.join(r'\input{sections/'+r['file']+'}' for r in records.values())
if not any(r['file'] in s for r in records.values()):s=s.replace(anchor,anchor+'\n'+new,1)
else:assert all(r['file'] in s for r in records.values())
p.write_text(s)
p=w/'notes/register_metadata.json';meta=json.loads(p.read_text())
for ident,rec in records.items():meta[ident]={k:v for k,v in rec.items() if k not in {'file','detail'}}
p.write_text(json.dumps(meta,indent=2,ensure_ascii=False)+'\n')
p=w/'SECTIONS_OVER_Q_report.md';lines=p.read_text().splitlines();assert lines[0]=='INCOMPLETE'
for i,line in enumerate(lines[:55]):
 if not line.startswith('| '):continue
 cells=[x.strip() for x in line.strip().strip('|').split('|')]
 if len(cells)!=3:continue
 for ident,rec in records.items():
  if cells[0] in {x.strip() for x in rec['answers'].split(';')}:
   if ident not in cells[1]:cells[1]+=', '+ident
   if rec['detail'] not in cells[2]:cells[2]+=' '+rec['detail']
 lines[i]='| '+' | '.join(cells)+' |'
heading='## Continued work: finite boundary separation and the full coherent norm fibre'
if heading not in lines:
 lines.extend(['',heading,'',stamp+': '+' '.join(r['detail'] for r in records.values()),'',
  'The boundary torsion proof uses literal degree-four divisors and the canonical smooth plane-quartic embedding to produce C4². The exact rational isogeny gives Jacobian reduction orders2000 and32768 at17 and31, whose common two-primary divisor is16 and whose odd prime divisors exclude all additional rational torsion. Explicit dyadic halving formulas give exponent2 in the isogeny target, so the Jacobian has no local order8. This identifies the precise finite coefficient level separating its four boundary classes.',
  'For the norm tower, the map from every global element to each physical-prime valuation module commutes with the actual field norm. A89 gives uniform three-divisibility away from the unique possible Frobenius fixed branch. It kills each outside-support coordinate, including families whose support might vary with the height. The finite S-class group supplies the induced topology needed to inject completed principal divisors into completed free divisors. Thus a completed field-norm family over-2 lies in the compact completed S-unit groups at every level. This makes the all-height obstruction exactly the balanced classes e_n already defined in A155. For the A162 changed seed the same conclusion holds with its first two entries fixed. This comparison does not prove those classes vanish.',
  'Both principal A1 assertions remain open. The next norm calculation targets the exact level-three class obstruction, and the remaining quotient/full-section scopes are unchanged.', ''])
p.write_text('\n'.join(lines)+'\n')
audit=stamp+' A164/A166 integrated after complete proof checks. A164 root and birational independently reran the exact certificate and audited the rational/local torsion maps. A166 root constructed the actual/completed fibre comparison and birational independently audited the entire saved proof and certificate, including the finite class-index completion injection. The moving-support argument was also independently confirmed by local. No nonemptiness claim for the infinite fibre is made.\n'
for name in ['notes/hour12_root_audits.md','notes/root_progress.md']:
 with(w/name).open('a')as f:f.write('\n'+audit)
proc=subprocess.run(['python',str(w/'code/build_register.py')],capture_output=True,text=True,check=True)
out='Integrated audited A164 and A166; A165 is reserved for the complete seed calculation.\n'+proc.stdout
Path(__file__).with_name('integrate_a164_a166_output.txt').write_text(out);print(out,end='')
